from collections.abc import Iterable

def flatten(iterable):
    """
    Flatten a nested iterable (any depth) into a flat list.
    Excludes None values. Treats strings and bytes as atomic (not iterated).
    """
    def _is_iterable(obj):
        return isinstance(obj, Iterable) and not isinstance(obj, (str, bytes, bytearray))

    result = []

    # If the top-level value is None, return empty list
    if iterable is None:
        return result

    # If top-level is not an iterable (or is a string/bytes), return it as single element (unless None)
    if not _is_iterable(iterable):
        return [iterable]

    for item in iterable:
        if item is None:
            continue
        if _is_iterable(item):
            result.extend(flatten(item))
        else:
            result.append(item)

    return result
